// ── All config comes from the frontend server — edit at http://localhost:3200 ──

// STEP 1 — Load config (try Docker service name first, then localhost)
let config = {};
for (const base of ['http://frontend:3200', 'http://localhost:3200']) {
  try {
    const r = await fetch(`${base}/api/config`);
    config = await r.json();
    break;
  } catch (_) {}
}

const prompt     = (config.prompt      || 'PPL Electric outage Pennsylvania today Lehigh Valley Scranton Harrisburg Lancaster').trim();
const smsTo      = config.sms_to       || '+1XXXXXXXXXX';
const TAVILY_KEY = config.tavily_apikey || '';
const OPENAI_KEY = config.openai_apikey || '';
const OPENAI_MODEL = config.openai_model || 'gpt-4o-mini';

if (!TAVILY_KEY) {
  await updateStatus({ sent: false, error: 'Tavily API key not set — add it at http://localhost:3200' });
  return [{ json: { shouldAlert: false, reason: 'Missing Tavily key' } }];
}
if (!OPENAI_KEY) {
  await updateStatus({ sent: false, error: 'OpenAI API key not set — add it at http://localhost:3200' });
  return [{ json: { shouldAlert: false, reason: 'Missing OpenAI key' } }];
}

// STEP 2 — Tavily web search
let searchData = { results: [], answer: '' };
try {
  const tavilyRes = await fetch('https://api.tavily.com/search', {
    method: 'POST',
    headers: { 'Authorization': `Bearer ${TAVILY_KEY}`, 'Content-Type': 'application/json' },
    body: JSON.stringify({ query: prompt, search_depth: 'advanced', max_results: 10, include_answer: true, include_raw_content: false, include_domains: ['pplweb.com','omap.prod.pplweb.com','poweroutage.us','wfmz.com','lehighvalleylive.com','mcall.com','pocononewstoday.com','pocono-record.com','wnep.com','citizensvoice.com','thetimes-tribune.com','timesleader.com','standardspeaker.com','pennlive.com','wgal.com','abc27.com','fox43.com','lancasteronline.com','ydr.com','gettysburgtimes.com','readingeagle.com','republicanherald.com','pressenterpriseonline.com','dailyitem.com','sungazette.com','pahomepage.com','dailylocal.com'] })
  });
  searchData = await tavilyRes.json();
} catch (e) {
  await updateStatus({ sent: false, error: 'Tavily failed: ' + e.message });
  return [{ json: { shouldAlert: false, reason: 'Tavily error: ' + e.message, smsTo } }];
}

const results = searchData.results || [];
const answer  = searchData.answer  || '';

if (results.length === 0) {
  await updateStatus({ sent: false, summary: 'No search results found' });
  return [{ json: { shouldAlert: false, reason: 'No Tavily results', smsTo } }];
}

// STEP 3 — OpenAI analysis
const resultsText = results.map((r, i) =>
  `[${i+1}] ${r.title}\nURL: ${r.url}\n${(r.content||'').substring(0,500)}`
).join('\n\n---\n\n');

const systemMsg = `You are a news monitoring agent for Pennsylvania electricity and power outages. Analyze web search results and determine whether they contain CURRENT news (within the last 48 hours) about real power outages or electricity issues in Pennsylvania.\n\nIf relevant current news found respond EXACTLY:\nALERT: YES\nSUMMARY: <1-2 sentences, max 200 characters>\nURL: <most relevant URL>\n\nIf none respond EXACTLY:\nALERT: NO\nREASON: <one-line explanation>`;

let aiResponse = '';
try {
  const openaiRes = await fetch('https://api.openai.com/v1/chat/completions', {
    method: 'POST',
    headers: { 'Authorization': `Bearer ${OPENAI_KEY}`, 'Content-Type': 'application/json' },
    body: JSON.stringify({
      model: OPENAI_MODEL,
      messages: [{ role: 'system', content: systemMsg }, { role: 'user', content: `Search: "${prompt}"\n\nAnswer: ${answer}\n\nResults:\n${resultsText}` }],
      max_tokens: 350, temperature: 0.1
    })
  });
  const aiData = await openaiRes.json();
  aiResponse = aiData.choices?.[0]?.message?.content?.trim() || '';
} catch (e) {
  await updateStatus({ sent: false, error: 'OpenAI failed: ' + e.message });
  return [{ json: { shouldAlert: false, reason: 'OpenAI error: ' + e.message, smsTo } }];
}

// STEP 4 — Parse response
const shouldAlert  = aiResponse.includes('ALERT: YES');
const summary = (aiResponse.match(/SUMMARY:\s*(.+?)(?:\n|$)/)?.[1] || 'Power outage news found in Pennsylvania').trim();
const url     = (aiResponse.match(/URL:\s*(.+?)(?:\n|$)/)?.[1]     || results[0]?.url || '').trim();

console.log(`shouldAlert=${shouldAlert} | ${summary.substring(0,60)}`);
if (!shouldAlert) await updateStatus({ sent: false, summary: 'No relevant current news' });

return [{ json: { shouldAlert, summary, url, aiResponse, resultCount: results.length, prompt, smsTo, timestamp: new Date().toISOString() } }];

async function updateStatus(payload) {
  for (const base of ['http://frontend:3200', 'http://localhost:3200']) {
    try {
      await fetch(`${base}/api/status`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(payload) });
      return;
    } catch (_) {}
  }
}

// ── Send WhatsApp via CallMeBot ─────────────────────────────────────────
// Credentials are stored in config.json and read via the frontend server.
// No $env needed — edit them at http://localhost:3200

const CONFIG_BASE = 'http://frontend:3200';

// Load config to get CallMeBot credentials
let config = {};
try {
  const cfgRes = await fetch(`${CONFIG_BASE}/api/config`);
  config = await cfgRes.json();
} catch (e) {
  try {
    const cfgRes = await fetch('http://localhost:3200/api/config');
    config = await cfgRes.json();
  } catch (_) {}
}

const phone  = config.callmebot_phone || '1XXXXXXXXXX';
const apiKey = config.callmebot_apikey || '';

const { summary, url, timestamp } = $input.item.json;

if (!apiKey) {
  console.warn('⚠️  callmebot_apikey not set in config.json. Add it at http://localhost:3200');
  await updateStatus({ sent: false, summary, url, error: 'CallMeBot API key not configured' });
  return [{ json: { sent: false, reason: 'CallMeBot API key missing — set it at http://localhost:3200', summary, url, timestamp } }];
}

// Detect a PPL county for a county-specific live link
const PPL_COUNTIES = ['Adams','Berks','Bradford','Carbon','Centre','Chester','Clinton','Columbia','Cumberland','Dauphin','Lackawanna','Lancaster','Lebanon','Lehigh','Luzerne','Lycoming','Monroe','Montgomery','Montour','Northampton','Northumberland','Pike','Schuylkill','Snyder','Sullivan','Susquehanna','Union','Wayne','Wyoming','York'];
const mentioned = PPL_COUNTIES.find(c => new RegExp(`\\b${c}\\b`, 'i').test(summary));
const countyLine = mentioned ? `\n📍 ${mentioned} County live: https://poweroutage.us/area/county/${mentioned.toLowerCase()}` : '';

// Build message
const message = `⚡ PA Power Alert!\n${summary}\n\n📰 ${url}${countyLine}\n🚨 Live PA outage alerts: https://poweroutage.us/dashboard/alerts`.substring(0, 1500);
const encodedMsg = encodeURIComponent(message);
const endpoint = `https://api.callmebot.com/whatsapp.php?phone=${phone}&text=${encodedMsg}&apikey=${apiKey}`;

try {
  const res = await fetch(endpoint);
  const body = await res.text();

  if (!res.ok || body.toLowerCase().includes('error')) {
    console.error('CallMeBot error:', body.substring(0, 200));
    await updateStatus({ sent: false, summary, url, error: body.substring(0, 200) });
    return [{ json: { sent: false, callmebotError: body.substring(0, 200), summary, url } }];
  }

  console.log('WhatsApp sent via CallMeBot ✅');
  await updateStatus({ sent: true, summary, url });
  return [{ json: { sent: true, to: phone, message, summary, url, timestamp } }];

} catch (e) {
  console.error('CallMeBot fetch failed:', e.message);
  await updateStatus({ sent: false, summary, url, error: e.message });
  return [{ json: { sent: false, error: e.message, summary, url } }];
}

async function updateStatus(payload) {
  for (const base of ['http://frontend:3200', 'http://localhost:3200']) {
    try {
      await fetch(`${base}/api/status`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload)
      });
      return;
    } catch (_) {}
  }
}

// No active outage found — send a 'all clear' WhatsApp notice

let config = {};
for (const base of ['http://frontend:3200', 'http://localhost:3200']) {
  try {
    const r = await fetch(`${base}/api/config`);
    config = await r.json();
    break;
  } catch (_) {}
}

const phone  = config.callmebot_phone  || '1XXXXXXXXXX';
const apiKey = config.callmebot_apikey || '';

if (!apiKey) {
  console.log('CallMeBot key not set — skipping no-outage notice');
  return [{ json: { sent: false, reason: 'No CallMeBot key' } }];
}

const now     = new Date().toLocaleString('en-US', { timeZone: 'America/New_York', month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit' });
const message = encodeURIComponent(`✅ No PPL Electric Utility Outages found.\nChecked: ${now} ET\nNext check in 8 hours.`);
const endpoint = `https://api.callmebot.com/whatsapp.php?phone=${phone}&text=${message}&apikey=${apiKey}`;

try {
  const res  = await fetch(endpoint);
  const body = await res.text();
  if (body.toLowerCase().includes('error')) {
    console.error('CallMeBot error:', body.substring(0, 200));
    return [{ json: { sent: false, error: body.substring(0, 200) } }];
  }
  console.log('No-outage notice sent ✅');

  // Update status on frontend server
  for (const base of ['http://frontend:3200', 'http://localhost:3200']) {
    try {
      await fetch(`${base}/api/status`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ sent: false, summary: 'No PPL Electric Utility Outages found' })
      });
      break;
    } catch (_) {}
  }

  return [{ json: { sent: true, notice: 'no_outage', timestamp: new Date().toISOString() } }];

} catch (e) {
  console.error('Fetch failed:', e.message);
  return [{ json: { sent: false, error: e.message } }];
}
